          "id": "contract-language",
          "address": "behavior.contract-language",
          "section": "behavior",
          "value": {
            "document-model": {
              "description": "A Seed is YAML with required metadata and nonempty scope, interfaces, behavior, constraints, freedom, and verifications sections; errors may be empty. Optional addressable sections are artifacts, state, security, environment, observability, and compatibility."
            },
            "metadata-tags": {
              "description": "Seed and genome metadata may include an optional tags field containing a simple list of nonempty strings. Tags preserve authored spelling and order and do not create contract addresses."
            },
            "address-normalization": {
              "description": "Addressable trees and ID-bearing lists compile into unique dotted addresses. IDs start alphanumeric and contain only letters, numbers, underscores, and hyphens. Known item properties remain fields rather than child addresses."
            },
            "requirements-readiness": {
              "description": "requirements is a temporary planning inbox. Blueprint and diff expose unresolved entries, but validation and verification start fail until it is absent or empty and the entries have been converted into the contract."
            },
            "artifacts-and-references": {
              "description": "Artifacts use repository-relative paths or HTTP(S) URLs and require descriptions. Items that mention local artifacts declare their IDs. Local, cross-Seed, and genome-qualified references must resolve or fail."
            },
            "policies": {
              "description": "Ordinary items default to local policy, security items default global, and explicit global policy items are supplied as context for every verification claim and checked by audit."
            },
            "id": "contract-language"
