          "value": {
            "resolution": {
              "description": "Genome lookup precedence is built-in, user, then repository. Requested genomes compose in order and local Seed values merge last. The winning address retains origin, ID, and path provenance.",
              "artifacts": [
                "genome-catalog"
              ]
            },
            "composition": {
              "description": "Recursive composition detects cycles and excessive depth. Keyed objects merge recursively, ID arrays merge by ID, addressable tree/list forms normalize together, ordinary arrays replace, and scalars replace."
            },
            "selectors": {
              "description": "String and object selectors include sections, addresses, subtrees, or artifacts with reference and artifact closure. Exclusions remove exact, subtree, ID, artifact, or glob matches after composition. Any unmatched selector fails."
            },
            "complete-exclusion": {
              "description": "Standalone !genome exclusions are order-independent, remove the genome transitively throughout the composed graph, and fail when unmatched."
            },
            "search": {
              "description": "Genome search uses case-insensitive substring matching across definition IDs, metadata names, summaries or descriptions, tags, and direct authored address names. --full-text additionally searches values within each direct address. Built-in, user, and repository origin filters apply; deterministic results report each genome's ID, origin, tags, match types, and matching addresses without treating inherited addresses as direct matches."
            },
